import{_ as a}from"./chunks/overview.DiC4zGUH.js";import{_ as r,a as o}from"./chunks/links.BEh3dZUz.js";import{_ as t}from"./chunks/settings.DZZEpno1.js";import{_ as i,o as l,c as s,a2 as d}from"./chunks/framework.BsAvorgW.js";const g=JSON.parse('{"title":"WebUI","description":"","frontmatter":{},"headers":[],"relativePath":"guide/webui.md","filePath":"guide/webui.md","lastUpdated":1784136889000}'),n={name:"guide/webui.md"};function c(p,e,m,h,u,b){return l(),s("div",null,[...e[0]||(e[0]=[d('<h1 id="webui" tabindex="-1">WebUI <a class="header-anchor" href="#webui" aria-label="Permalink to &quot;WebUI&quot;">​</a></h1><p>WebUI 默认运行在 <code>17892</code> 端口。首次进入需要用启动日志里的 Token 创建管理员，之后使用管理员账号登录。</p><h2 id="在线交互演示" tabindex="-1">在线交互演示 <a class="header-anchor" href="#在线交互演示" aria-label="Permalink to &quot;在线交互演示&quot;">​</a></h2><p>下面是 WebUI 的纯静态交互演示。数据、账号、节点和代理地址均为虚构示例，页面不会连接 SelenaProxy 后端，也不会上传或持久化你填写的内容。</p><div class="webui-demo-frame"><iframe src="/SelenaProxy-docs/webui-demo/" title="SelenaProxy WebUI 静态交互演示" loading="lazy" referrerpolicy="no-referrer"></iframe></div><p class="webui-demo-open"><a href="/SelenaProxy-docs/webui-demo/" target="_blank" rel="noopener noreferrer">在新窗口打开完整演示</a></p><div class="warning custom-block"><p class="custom-block-title">演示模式</p><p>演示中的“保存账号”“保存配置”和“复制链接”只用于体验界面效果。刷新页面后会恢复默认示例；真实部署后，WebUI 才会连接本机 SelenaProxy 服务并保存配置。</p></div><h2 id="总览" tabindex="-1">总览 <a class="header-anchor" href="#总览" aria-label="Permalink to &quot;总览&quot;">​</a></h2><p>查看健康节点、活动连接、累计提取、请求结果和流量统计。</p><p><img src="'+a+'" alt="运行总览"></p><h2 id="账号" tabindex="-1">账号 <a class="header-anchor" href="#账号" aria-label="Permalink to &quot;账号&quot;">​</a></h2><p>添加、编辑、停用或删除代理账号。保存期间表单会锁定，避免重复提交。</p><p><img src="'+r+'" alt="账号管理"></p><h2 id="链接" tabindex="-1">链接 <a class="header-anchor" href="#链接" aria-label="Permalink to &quot;链接&quot;">​</a></h2><p>一键复制各账号的完整代理地址，并打开单账号用量面板。页面上不会直接显示真实密码。</p><p><img src="'+o+'" alt="链接与用量"></p><h2 id="节点与日志" tabindex="-1">节点与日志 <a class="header-anchor" href="#节点与日志" aria-label="Permalink to &quot;节点与日志&quot;">​</a></h2><ul><li><strong>节点</strong>：查看当前短效代理、剩余安全时间、活动连接和失败次数。</li><li><strong>日志</strong>：查看认证失败、白名单拦截、供应商提取和节点轮换记录。</li></ul><h2 id="设置" tabindex="-1">设置 <a class="header-anchor" href="#设置" aria-label="Permalink to &quot;设置&quot;">​</a></h2><p>修改供应商 API、代理池策略、监听地址和目标白名单。设置保存后会热更新，不需要手动重启。</p><p><img src="'+t+'" alt="运行设置"></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>通过 HTTPS 反向代理公开 WebUI 时，请让反向代理传递 <code>X-Forwarded-Proto: https</code>，登录 Cookie 会自动附加 Secure 属性。</p></div>',22)])])}const x=i(n,[["render",c]]);export{g as __pageData,x as default};
